// Compare only editable Admin account fields against the values that opened
// the editor. Never obtain or retain an existing password from server records.
const ACCOUNT_FIELDS = [
  "full_name", "username", "role", "sales_roles",
  "can_import_export", "can_order_export", "can_view_resources",
  "employment_type", "can_work_pause", "force_password_reset", "is_deactivated",
  "notification_prefs"
];
const own = (value, field) => Object.prototype.hasOwnProperty.call(value, field);
const stableRoles = value => Array.isArray(value)
  ? [...new Set(value)].sort()
  : value;

export function createAdminAccountDraft(record) {
  return {
    full_name: record.full_name || "",
    username: record.username || "",
    password_hash: "",
    role: record.role || "user",
    sales_roles: record.sales_roles || ["Task Assigned"],
    can_import_export: record.can_import_export || false,
    can_order_export: record.role === "admin" && record.can_order_export === true,
    can_view_resources: record.role === "admin" || record.can_view_resources || false,
    employment_type: record.employment_type || "hourly",
    can_work_pause: record.can_work_pause === true,
    force_password_reset: record.force_password_reset === true,
    is_deactivated: record.is_deactivated === true,
    notification_prefs: record.notification_prefs && typeof record.notification_prefs === "object"
      ? { automation_emails: record.notification_prefs.automation_emails !== false }
      : { automation_emails: true }
  };
}

// Only fields edited from this verified Account version belong in a write.
// Role/order-export/resources dependencies are still enforced by the backend.
// Passwords are never part of Account writes or account field reconciliation.
export function getChangedAdminAccountFields(record, draft) {
  if (!record?.id || !record?.email || !record?.updated_date ||
      !draft || typeof draft !== "object" || Array.isArray(draft) ||
      ACCOUNT_FIELDS.some(field => !own(draft, field))) {
    throw new Error("Account edits require a verified employee and complete draft.");
  }
  const baseline = createAdminAccountDraft(record);
  const patch = {};
  for (const field of ACCOUNT_FIELDS) {
    const before = field === "sales_roles" ? stableRoles(baseline[field]) : baseline[field];
    const after = field === "sales_roles" ? stableRoles(draft[field]) : draft[field];
    if (JSON.stringify(before) !== JSON.stringify(after)) {
      patch[field] = field === "sales_roles" && Array.isArray(draft[field])
        ? [...new Set(draft[field])]
        : draft[field];
    }
  }
  return patch;
}

export function hasUnsavedAdminAccountDraft(baseline, draft) {
  if (!baseline || !draft || typeof baseline !== "object" ||
      typeof draft !== "object" || Array.isArray(baseline) || Array.isArray(draft)) return true;
  // Any new Time Clock password is a draft. The previous password is never
  // included in the baseline or compared to a server field.
  if (String(draft.password_hash || "").length > 0) return true;
  return ACCOUNT_FIELDS.some(field => {
    if (!own(baseline, field) || !own(draft, field)) return true;
    const before = field === "sales_roles" ? stableRoles(baseline[field]) : baseline[field];
    const after = field === "sales_roles" ? stableRoles(draft[field]) : draft[field];
    return JSON.stringify(before) !== JSON.stringify(after);
  });
}

// Local-only field choice planner for interrupted Admin Account saves.
// No writes. All permissions remain subject to backend authorization and CAS.
import { createAdminAccountDraft } from "./adminAccountDraft.js";

const FIELDS = [
  ["full_name","Full name"], ["username","Time Clock username"],
  ["role","Account role"], ["sales_roles","Sales Pipeline assignments"],
  ["can_import_export","Import/export permission"],
  ["can_order_export","Order Form export permission"],
  ["can_view_resources","Resources permission"],
  ["employment_type","Employment type"], ["can_work_pause","Work Pause permission"]
];
const FIELDS_KEYS=FIELDS.map(([key])=>key);
const equal=(key,a,b)=>key==="sales_roles"
  ? JSON.stringify([...new Set(a||[])].sort())===JSON.stringify([...new Set(b||[])].sort())
  : Object.is(a,b);
const own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
const copy=value=>Array.isArray(value)?[...value]:value;

export function planAccountFieldResolution({baseline,attempted,latest,draft,choices={}}) {
  const records=[baseline,attempted,latest,draft,choices];
  if(records.some(item=>!item||typeof item!=="object"||Array.isArray(item))||
     FIELDS_KEYS.some(key=>!own(attempted,key)||!own(draft,key))) {
    throw new Error("Account field review requires complete, scoped drafts.");
  }
  if(Object.entries(choices).some(([key,value])=>
    !FIELDS_KEYS.includes(key)||!["latest","mine"].includes(value))) {
    throw new Error("Unknown Account field resolution choice.");
  }
  const original=createAdminAccountDraft(baseline);
  const remote=createAdminAccountDraft(latest);
  const result={...remote,sales_roles:copy(remote.sales_roles),password_hash:draft.password_hash||""};
  const fields=[];
  for(const [key,label] of FIELDS){
    const tried=!equal(key,original[key],attempted[key]);
    const remoteChanged=!equal(key,original[key],remote[key]);
    const editedLater=!equal(key,attempted[key],draft[key]);
    if(!tried&&!remoteChanged&&!editedLater) continue;
    const explicit=choices[key];
    if(explicit!==undefined && explicit!=="latest" && explicit!=="mine") {
      throw new Error("Unknown Account field resolution choice.");
    }
    // Never discard edits made after the failed request without a deliberate
    // choice. Everything else defaults to the newly verified remote version.
    const selected=explicit || (editedLater?"mine":"latest");
    result[key]=copy(selected==="mine"?draft[key]:remote[key]);
    fields.push({key,label,selected,tried,remoteChanged,editedLater,
      sensitive:["role","sales_roles","can_import_export","can_order_export","can_view_resources"].includes(key),
      matchesLatest:equal(key,draft[key],remote[key])});
  }
  const adjustments=[];
  if(result.role!=="admin" && result.can_order_export!==false){
    result.can_order_export=false;
    adjustments.push("Order Form export is disabled for non-admin accounts.");
  }
  if(result.role==="admin" && result.can_view_resources!==true){
    result.can_view_resources=true;
    adjustments.push("Administrators have Resources access enabled.");
  }
  return {
    fields, draft:result, adjustments,
    counts:{
      useLatest:fields.filter(field=>field.selected==="latest").length,
      useMine:fields.filter(field=>field.selected==="mine").length,
      privilegedMine:fields.filter(field=>field.sensitive&&field.selected==="mine"&&!field.matchesLatest).length
    }
  };
}

// Read-only reconciliation of an unverified Admin Account write.
// Inspect only editable account fields; never retain Time Clock passwords.
import { createAdminAccountDraft } from "./adminAccountDraft.js";

const FIELDS = [
  "full_name", "username", "role", "sales_roles", "can_import_export",
  "can_order_export", "can_view_resources", "employment_type", "can_work_pause"
];
const same = (field, a, b) => field === "sales_roles"
  ? JSON.stringify([...new Set(a || [])].sort()) === JSON.stringify([...new Set(b || [])].sort())
  : Object.is(a, b);

// When the attempted values are observed in the verified record, retain only
// new edits made after the submit began. Preserve all verified remote-only
// changes. Password is always a local draft, never part of the Account read.
export function rebaseAppliedAccountDraft({ latest, attempted, current }) {
  const result = createAdminAccountDraft(latest);
  for (const field of FIELDS) {
    if (!same(field, current?.[field], attempted?.[field])) {
      result[field] = current?.[field];
    }
  }
  result.password_hash = current?.password_hash || "";
  return result;
}

// A verification preview is not a permanent authorization. Check the whole
// editable Account surface and its record version again before accepting it.
// Fail closed on missing identities/versions, including legacy rows.
export function isSameVerifiedAccountSnapshot(reviewed, fresh) {
  if (!reviewed?.id || !reviewed?.email || !reviewed?.updated_date ||
      !fresh?.id || !fresh?.email || !fresh?.updated_date ||
      reviewed.id !== fresh.id || reviewed.email !== fresh.email ||
      reviewed.updated_date !== fresh.updated_date) return false;
  const prior = createAdminAccountDraft(reviewed);
  const current = createAdminAccountDraft(fresh);
  return FIELDS.every(field =>
    same(field, prior[field], current[field]) &&
    // Normalized editor defaults can mask raw invalid permission states.
    // Preserve strict equality for authority-bearing fields instead of
    // treating an unexpected grant as unchanged.
    (!["can_order_export", "can_view_resources"].includes(field) ||
      Object.is(reviewed[field], fresh[field]))
  );
}

export function compareUnverifiedAccountSave({ baseline, attempted, latest }) {
  if (![baseline, attempted, latest].every(value =>
    value && typeof value === "object" && !Array.isArray(value))) {
    throw new Error("Account verification requires complete records.");
  }
  const oldFields = createAdminAccountDraft(baseline);
  const latestFields = createAdminAccountDraft(latest);
  // Attempted must be an independent immutable snapshot from before the write.
  if (!FIELDS.every(field => Object.prototype.hasOwnProperty.call(attempted, field))) {
    throw new Error("Account write snapshot is incomplete.");
  }
  const edited = FIELDS.filter(field => !same(field, oldFields[field], attempted[field]));
  const applied = edited.filter(field => same(field, latestFields[field], attempted[field]));
  const unchanged = edited.filter(field => same(field, latestFields[field], oldFields[field]));
  const diverged = edited.filter(field =>
    !same(field, latestFields[field], oldFields[field]) &&
    !same(field, latestFields[field], attempted[field]));
  const status = diverged.length || (applied.length && unchanged.length)
    ? "mixed" : applied.length === edited.length
      ? "applied" : "unchanged";
  return {
    status, editedCount: edited.length,
    appliedCount: applied.length, unchangedCount: unchanged.length,
    divergentCount: diverged.length,
    // Field labels only, no HR/account values or passwords.
    fields: edited.map(field => ({
      key: field, label: field.replaceAll("_", " "),
      outcome: diverged.includes(field) ? "different" :
        applied.includes(field) ? "applied" : "unchanged"
    }))
  };
}
